arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Content-Type: application/json" -d '{"token":"***","types":"public_channel,private_channel","exclude_archived":false,"limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok' if d.get('ok') else d)
for key in ('channels','groups'):
    for c in d.get(key,[]):
        if 'incident' in c.get('name','').lower():
            print(key, c['id'], c['name'], 'archived' if c.get('is_archived') else 'active')
"

